mapper.select:
SELECT
  csf.FACTORY_CODE,
  csf.STRUCTURE_NAME,
  csf.TURNOVER_MONTH,
  csf.MIN_VULCANIZING_MACHINE
FROM t_dp_cycle_struct_config csf
       INNER JOIN T_MP_STRUCTURE_ALLOCATION msa
                  ON msa.STRUCTURE_NAME = csf.STRUCTURE_NAME
                    AND msa.FACTORY_CODE = #{factoryCode,jdbcType=VARCHAR}
                    AND msa.`YEAR` = #{year,jdbcType=DECIMAL}
                    AND msa.`MONTH` = #{month,jdbcType=DECIMAL}
                    AND msa.MONTH_PLAN_VERSION = #{monthPlanVersion,jdbcType=VARCHAR}
                    AND msa.PRODUCTION_VERSION = #{productionVersion,jdbcType=VARCHAR}
                    AND msa.IS_DELETE = 0
WHERE csf.IS_DELETE = 0

  AND csf.STRUCTURE_NAME = #{structureName}
